mapper.select:
SELECT 1 FROM batch.import_ingress_scan_storage_lease
 WHERE storage_id = #{storageId} AND lease_owner = #{owner} AND fence = #{storageFence}
   AND lease_until > clock_timestamp() FOR UPDATE

SELECT 1 FROM batch.import_ingress_scan_state
 WHERE scope_id = #{scopeId} AND lease_owner = #{owner} AND fence = #{fence}
   AND lease_until > clock_timestamp() FOR UPDATE

SELECT  FROM batch.import_ingress_scan_object
 WHERE scope_id = #{lease.scopeId} AND seen_window = #{lease.windowId} AND id > #{lease.afterObjectId} AND is_manifest
 ORDER BY id LIMIT #{limit}

SELECT  FROM batch.import_ingress_scan_object
 WHERE scope_id = #{lease.scopeId} AND id > #{lease.applyAfterId} AND id <= #{lease.applyUpperId}
 ORDER BY id LIMIT #{limit}

mapper.delete:
DELETE FROM batch.import_ingress_scan_object WHERE id IN (
  SELECT id FROM batch.import_ingress_scan_object
   WHERE scope_id = #{lease.scopeId} AND seen_cycle < #{lease.cycle} ORDER BY seen_cycle, id LIMIT #{limit}
)

mapper.update:
UPDATE batch.import_ingress_scan_state
   SET phase = #{phase}, list_marker = #{marker,jdbcType=VARCHAR}, after_object_id = #{afterObjectId}, cycle = #{cycle}, updated_at = clock_timestamp()
 WHERE scope_id = #{lease.scopeId} AND lease_owner = #{lease.owner} AND fence = #{lease.fence}
